/* Shared platform primitives. Domain modules own their server collections and
   use this namespace for rendering, formatting and common interaction rules. */
(() => {
  'use strict';
  const root = globalThis;
  if (root.bamcoEnterprise) return;
  const q = (selector, scope = document) => scope?.querySelector?.(selector);
  const qa = (selector, scope = document) => [...(scope?.querySelectorAll?.(selector) || [])];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const fa = value => String(value ?? '').replace(/\d/g, digit => 'Û°Û±Û²Û³Û´ÛµÛ¶Û·Û¸Û¹'[digit]);
  const money = (value, currency = 'Ø±ÛŒØ§Ù„') => `${fa(Number(value || 0).toLocaleString('en-US'))} ${esc(currency)}`;
  const date = value => value ? (typeof jalaliText === 'function' ? jalaliText(value) : String(value).slice(0, 10)) : 'â€”';
  const dateTime = value => value ? (typeof jalaliDateTime === 'function' ? jalaliDateTime(value) : String(value)) : 'â€”';
  const progress = value => `<div class="enterprise-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.max(0, Math.min(100, Number(value || 0)))}"><span style="width:${Math.max(0, Math.min(100, Number(value || 0)))}%"></span></div>`;
  const status = {
    draft: 'Ù¾ÛŒØ´â€ŒÙ†ÙˆÛŒØ³', planned: 'Ø¨Ø±Ù†Ø§Ù…Ù‡â€ŒØ±ÛŒØ²ÛŒâ€ŒØ´Ø¯Ù‡', active: 'ÙØ¹Ø§Ù„', in_progress: 'Ø¯Ø± Ø­Ø§Ù„ Ø§Ø¬Ø±Ø§', paused: 'Ù…ØªÙˆÙ‚Ù', waiting: 'Ø¯Ø± Ø§Ù†ØªØ¸Ø§Ø±', completed: 'ØªÚ©Ù…ÛŒÙ„â€ŒØ´Ø¯Ù‡', closed: 'Ø¨Ø³ØªÙ‡â€ŒØ´Ø¯Ù‡', cancelled: 'Ù„ØºÙˆØ´Ø¯Ù‡',
    initial: 'Ø«Ø¨Øª Ø§ÙˆÙ„ÛŒÙ‡', pending_approval: 'Ø¯Ø± Ø§Ù†ØªØ¸Ø§Ø± ØªØ£ÛŒÛŒØ¯', approved: 'ØªØ£ÛŒÛŒØ¯Ø´Ø¯Ù‡', awaiting_payment: 'Ø¯Ø± Ø§Ù†ØªØ¸Ø§Ø± Ù¾Ø±Ø¯Ø§Ø®Øª', partially_paid: 'Ù¾Ø±Ø¯Ø§Ø®Øª Ø¬Ø²Ø¦ÛŒ', settled: 'ØªØ³ÙˆÛŒÙ‡â€ŒØ´Ø¯Ù‡', overdue: 'Ø³Ø±Ø±Ø³ÛŒØ¯ Ú¯Ø°Ø´ØªÙ‡', returned: 'Ø¨Ø±Ú¯Ø´Øª Ø¨Ø±Ø§ÛŒ Ø§ØµÙ„Ø§Ø­'
  };
  const statusText = value => status[value] || value || 'â€”';
  const person = id => (state.profiles || []).find(profile => String(profile.id) === String(id));
  const personName = id => person(id)?.display_name || person(id)?.full_name || person(id)?.email || 'â€”';
  const setBusy = (button, busy, label) => { if (!button) return; button.disabled = !!busy; if (busy) { button.dataset.previousLabel = button.textContent; button.textContent = label || 'Ø¯Ø± Ø­Ø§Ù„ Ø°Ø®ÛŒØ±Ù‡â€¦'; } else if (button.dataset.previousLabel) { button.textContent = button.dataset.previousLabel; delete button.dataset.previousLabel; } };
  const fetchRows = (table, query) => selectAll(table, query || 'select=*');
  const removeRows = (table, filter) => api(`/rest/v1/${table}?${filter}`, { method: 'DELETE', prefer: 'return=minimal' });
  const refresh = () => { if (typeof window.refresh === 'function') return window.refresh(); return Promise.resolve(); };
  const notify = (message, error = false) => typeof toast === 'function' ? toast(message, error) : undefined;
  const viewActive = view => !q(`#${view}View`)?.classList.contains('hidden');
  root.bamcoEnterprise = Object.freeze({ q, qa, esc, fa, money, date, dateTime, progress, statusText, personName, setBusy, fetchRows, removeRows, refresh, notify, viewActive });
})();
;

