/* Organization source of truth: positions, people, roles and approval policy. */
(() => {
  'use strict';
  const E = window.bamcoEnterprise;
  if (!E) return;
  const { q, qa, esc, fa, fetchRows, setBusy, notify } = E;
  const model = { roles: [], units: [], positions: [], assignments: [], policies: [], loaded: false, selected: null };
  const root = () => q('#organizationFeatureRoot');
  const role = id => model.roles.find(item => String(item.id) === String(id));
  const position = id => model.positions.find(item => String(item.id) === String(id));
  const assignment = id => model.assignments.find(item => String(item.position_id) === String(id) && item.is_primary && !item.valid_to);
  function treeRows(parent = null, depth = 0, seen = new Set()) {
    return model.positions.filter(item => (item.parent_position_id || null) === parent && !seen.has(item.id)).flatMap(item => {
      seen.add(item.id); return [{ item, depth }, ...treeRows(item.id, depth + 1, seen)];
    });
  }
  function render() {
    const host = root(); if (!host) return;
    const rows = treeRows();
    host.innerHTML = `<div class="feature-toolbar enterprise-toolbar"><div><h3>Ø³Ø§Ø®ØªØ§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ</h3><p>Ø³Ù…ØªØŒ Ù†Ù‚Ø´ Ùˆ Ø´Ø®Øµ Ø¬Ø¯Ø§ Ù†Ú¯Ù‡Ø¯Ø§Ø±ÛŒ Ù…ÛŒâ€ŒØ´ÙˆÙ†Ø¯Ø› Ù‡Ù…ÛŒÙ† Ø¯Ø±Ø®Øª Ù…Ù†Ø¨Ø¹ Ø¯Ø³ØªØ±Ø³ÛŒ Ùˆ Ú¯Ø±Ø¯Ø´ ØªØ£ÛŒÛŒØ¯ Ø§Ø³Øª.</p></div><div class="feature-toolbar-actions"><button type="button" class="primary" data-org-action="position">Ø³Ù…Øª Ø¬Ø¯ÛŒØ¯</button><button type="button" class="ghost" data-org-action="unit">ÙˆØ§Ø­Ø¯ Ø¬Ø¯ÛŒØ¯</button><button type="button" class="ghost" data-org-action="refresh">ØªØ§Ø²Ù‡â€ŒØ³Ø§Ø²ÛŒ</button></div></div>
      <div class="enterprise-grid organization-grid"><section class="panel"><div class="panel-head"><h3>Ù†Ù…ÙˆØ¯Ø§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ</h3><span class="enterprise-count">${fa(model.positions.length)} Ø³Ù…Øª</span></div><div class="organization-tree">${rows.length ? rows.map(({ item, depth }) => { const r = role(item.role_id), a = assignment(item.id); return `<article class="organization-node" style="--tree-depth:${depth}" data-position-id="${item.id}"><div><strong>${esc(item.title)}</strong><small>${esc(r?.title || 'Ø¨Ø¯ÙˆÙ† Ù†Ù‚Ø´')} Â· ${esc(a ? E.personName(a.user_id) : 'Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø®Ø§Ù„ÛŒ')}</small></div><div class="organization-node-actions"><button type="button" class="ghost" data-org-edit="${item.id}">ÙˆÛŒØ±Ø§ÛŒØ´</button><button type="button" class="ghost" data-org-child="${item.id}">Ø²ÛŒØ±Ù…Ø¬Ù…ÙˆØ¹Ù‡ Ø¬Ø¯ÛŒØ¯</button></div></article>`; }).join('') : '<div class="empty">Ù‡Ù†ÙˆØ² Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø«Ø¨Øª Ù†Ø´Ø¯Ù‡ Ø§Ø³Øª.</div>'}</div></section><section class="panel"><div class="panel-head"><h3>Ù†Ù‚Ø´â€ŒÙ‡Ø§ Ùˆ Ø³ÛŒØ§Ø³Øªâ€ŒÙ‡Ø§ÛŒ ØªØ£ÛŒÛŒØ¯</h3></div><div class="organization-role-list">${model.roles.filter(item => item.active).map(item => `<div><b>${esc(item.title)}</b><span>Ø³Ø·Ø­ ${fa(item.level_no)}</span></div>`).join('')}</div><div class="organization-policy-list">${model.policies.map(item => `<div><b>${esc(item.title)}</b><span>Ø­Ø¯Ø§Ú©Ø«Ø± ${fa(item.max_levels)} Ø³Ø·Ø­ Ø¨Ø§Ù„Ø§Ø¯Ø³Øª</span></div>`).join('') || '<div class="empty">Ø³ÛŒØ§Ø³ØªÛŒ Ø«Ø¨Øª Ù†Ø´Ø¯Ù‡ Ø§Ø³Øª.</div>'}</div></section></div>
      <dialog id="organizationPositionDialog" class="modal enterprise-modal"><form id="organizationPositionForm"><div class="modal-head"><div><h3>Ø«Ø¨Øª Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ</h3><p>Ø¨Ø±Ø§ÛŒ Ú¯Ø±Ø¯Ø´ ØªØ£ÛŒÛŒØ¯ØŒ Ø¨Ø§Ù„Ø§Ø¯Ø³Øª Ùˆ Ø´Ø®Øµ ÙØ¹Ø§Ù„ Ø¨Ø§ÛŒØ¯ Ù…Ø´Ø®Øµ Ø¨Ø§Ø´Ù†Ø¯.</p></div><button type="button" data-org-close>Ã—</button></div><input type="hidden" name="id"><div class="form-grid"><label>Ø¹Ù†ÙˆØ§Ù† Ø³Ù…Øª<input name="title" required></label><label>Ú©Ø¯ Ø³Ù…Øª<input name="code" required></label><label>Ù†Ù‚Ø´<select name="role_id" required></select></label><label>ÙˆØ§Ø­Ø¯ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ<select name="unit_id"><option value="">Ø¨Ø¯ÙˆÙ† ÙˆØ§Ø­Ø¯</option></select></label><label class="span-2">Ø¨Ø§Ù„Ø§Ø¯Ø³Øª<select name="parent_position_id"><option value="">Ø¨Ø¯ÙˆÙ† Ø¨Ø§Ù„Ø§Ø¯Ø³Øª</option></select></label><label class="span-2">Ø´Ø®Øµ Ù…Ù†ØµÙˆØ¨<select name="user_id"><option value="">Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø®Ø§Ù„ÛŒ</option></select></label></div><div class="modal-actions"><button type="button" class="ghost" data-org-close>Ø§Ù†ØµØ±Ø§Ù</button><button type="submit" class="primary">Ø°Ø®ÛŒØ±Ù‡ Ø¬Ø§ÛŒÚ¯Ø§Ù‡</button></div></form></dialog>
      <dialog id="organizationUnitDialog" class="modal enterprise-modal"><form id="organizationUnitForm"><div class="modal-head"><div><h3>Ø«Ø¨Øª ÙˆØ§Ø­Ø¯ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ</h3></div><button type="button" data-org-close>Ã—</button></div><div class="form-grid"><label>Ø¹Ù†ÙˆØ§Ù† ÙˆØ§Ø­Ø¯<input name="title" required></label><label>Ú©Ø¯ ÙˆØ§Ø­Ø¯<input name="code" required></label><label class="span-2">ÙˆØ§Ø­Ø¯ Ù…Ø§Ø¯Ø±<select name="parent_unit_id"><option value="">Ø¨Ø¯ÙˆÙ† ÙˆØ§Ø­Ø¯ Ù…Ø§Ø¯Ø±</option>${model.units.map(item => `<option value="${item.id}">${esc(item.title)}</option>`).join('')}</select></label></div><div class="modal-actions"><button type="button" class="ghost" data-org-close>Ø§Ù†ØµØ±Ø§Ù</button><button type="submit" class="primary">Ø°Ø®ÛŒØ±Ù‡ ÙˆØ§Ø­Ø¯</button></div></form></dialog>`;
    fillPositionForm(); bind();
  }
  function fillPositionForm(current = null) {
    const form = q('#organizationPositionForm'); if (!form) return;
    form.elements.role_id.innerHTML = model.roles.filter(item => item.active).map(item => `<option value="${item.id}">${esc(item.title)}</option>`).join('');
    form.elements.unit_id.innerHTML = '<option value="">Ø¨Ø¯ÙˆÙ† ÙˆØ§Ø­Ø¯</option>' + model.units.filter(item => item.active).map(item => `<option value="${item.id}">${esc(item.title)}</option>`).join('');
    form.elements.parent_position_id.innerHTML = '<option value="">Ø¨Ø¯ÙˆÙ† Ø¨Ø§Ù„Ø§Ø¯Ø³Øª</option>' + model.positions.filter(item => item.active && String(item.id) !== String(current?.id)).map(item => `<option value="${item.id}">${esc(item.title)}</option>`).join('');
    form.elements.user_id.innerHTML = '<option value="">Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø®Ø§Ù„ÛŒ</option>' + (state.profiles || []).filter(item => item.active !== false).map(item => `<option value="${item.id}">${esc(item.display_name || item.full_name || item.email)}</option>`).join('');
    if (current) { for (const key of ['id','title','code','role_id','unit_id','parent_position_id']) form.elements[key].value = current[key] ?? ''; form.elements.user_id.value = assignment(current.id)?.user_id || ''; }
  }
  function openPosition(id = null, parent = null) { const form = q('#organizationPositionForm'); if (!form) return; form.reset(); fillPositionForm(id ? position(id) : null); if (id) fillPositionForm(position(id)); else if (parent) form.elements.parent_position_id.value = String(parent); q('#organizationPositionDialog').showModal(); }
  async function savePosition(event) {
    event.preventDefault(); const form = event.currentTarget, button = q('[type=submit]', form), id = form.elements.id.value;
    const payload = { title: form.elements.title.value.trim(), code: form.elements.code.value.trim(), role_id: Number(form.elements.role_id.value), unit_id: form.elements.unit_id.value ? Number(form.elements.unit_id.value) : null, parent_position_id: form.elements.parent_position_id.value ? Number(form.elements.parent_position_id.value) : null };
    if (!payload.title || !payload.code) return notify('Ø¹Ù†ÙˆØ§Ù† Ùˆ Ú©Ø¯ Ø³Ù…Øª Ø§Ù„Ø²Ø§Ù…ÛŒ Ø§Ø³Øª.', true);
    setBusy(button, true); try { const rows = id ? await update('organization_positions', `id=eq.${encodeURIComponent(id)}`, payload) : await insert('organization_positions', { ...payload, created_by: state.user.id }); const positionId = id || rows?.[0]?.id; await removeRows('organization_position_assignments', `position_id=eq.${encodeURIComponent(positionId)}`); if (form.elements.user_id.value) await insert('organization_position_assignments', { position_id: positionId, user_id: form.elements.user_id.value, assigned_by: state.user.id, is_primary: true }); q('#organizationPositionDialog').close(); notify('Ø³Ø§Ø®ØªØ§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø°Ø®ÛŒØ±Ù‡ Ø´Ø¯.'); await load(); } catch (error) { notify(error.message, true); } finally { setBusy(button, false); }
  }
  async function saveUnit(event) { event.preventDefault(); const form = event.currentTarget, button = q('[type=submit]', form); setBusy(button, true); try { await insert('organization_units', { title: form.elements.title.value.trim(), code: form.elements.code.value.trim(), parent_unit_id: form.elements.parent_unit_id.value ? Number(form.elements.parent_unit_id.value) : null, created_by: state.user.id }); q('#organizationUnitDialog').close(); notify('ÙˆØ§Ø­Ø¯ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø°Ø®ÛŒØ±Ù‡ Ø´Ø¯.'); await load(); } catch (error) { notify(error.message, true); } finally { setBusy(button, false); } }
  function bind() { const host = root(); if (!host || host.dataset.bound === '1') return; host.dataset.bound = '1'; host.addEventListener('click', event => { const action = event.target.closest('[data-org-action]')?.dataset.orgAction; if (action === 'position') openPosition(); if (action === 'unit') q('#organizationUnitDialog')?.showModal(); if (action === 'refresh') void load(); const edit = event.target.closest('[data-org-edit]'); if (edit) openPosition(edit.dataset.orgEdit); const child = event.target.closest('[data-org-child]'); if (child) openPosition(null, child.dataset.orgChild); if (event.target.closest('[data-org-close]')) event.target.closest('dialog')?.close(); }); host.addEventListener('submit', event => { if (event.target.id === 'organizationPositionForm') void savePosition(event); if (event.target.id === 'organizationUnitForm') void saveUnit(event); }); }
  async function load() { if (!root() || !state.profile || !isManager()) return; try { const [roles, units, positions, assignments, policies] = await Promise.all([fetchRows('organization_roles', 'select=*&active=eq.true&order=level_no.asc'), fetchRows('organization_units', 'select=*&active=eq.true&order=title.asc'), fetchRows('organization_positions', 'select=*&active=eq.true&order=title.asc'), fetchRows('organization_position_assignments', 'select=*&order=id.desc'), fetchRows('approval_policies', 'select=*&active=eq.true&order=id.asc')]); Object.assign(model, { roles, units, positions, assignments, policies, loaded: true }); render(); } catch (error) { if (root()) root().innerHTML = `<div class="panel enterprise-error">${esc(error.message)}</div>`; } }
  function boot() { if (!root()) return; render(); document.addEventListener('click', event => { if (event.target.closest('#nav [data-view="organization"]')) void load(); }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true }); else boot();
  window.bamcoOrganization = { load, model };
})();
;

/* source: assets/js/approval-center.js */
/* Central workbench presentation for the organization-based Approval Engine. */
(() => {
  'use strict';
  const E = window.bamcoEnterprise; if (!E) return;
  const { q, esc, fa, dateTime, notify } = E;
  let filter = 'action';
  const labels = { create: 'ØªØ¹Ø±ÛŒÙ ÙˆØ¸ÛŒÙÙ‡', update: 'ÙˆÛŒØ±Ø§ÛŒØ´ ÙˆØ¸ÛŒÙÙ‡', status: 'ØªØºÛŒÛŒØ± ÙˆØ¶Ø¹ÛŒØª', priority: 'ØªØºÛŒÛŒØ± Ø§ÙˆÙ„ÙˆÛŒØª', description: 'ØªØºÛŒÛŒØ± ØªÙˆØ¶ÛŒØ­Ø§Øª', complete: 'Ø§Ø¹Ù„Ø§Ù… Ø§Ù†Ø¬Ø§Ù…', delete: 'Ø­Ø°Ù ÙˆØ¸ÛŒÙÙ‡', due_date: 'ØªØºÛŒÛŒØ± ØªØ§Ø±ÛŒØ® Ù¾Ø§ÛŒØ§Ù†' };
  const route = id => (state.requestRoutes || []).find(item => String(item.request_id) === String(id));
  const allRows = () => [...(state.requests || []), ...(state.requestHistory || [])].filter((item, index, rows) => rows.findIndex(row => String(row.id) === String(item.id)) === index);
  const matches = row => { const mine = String(row.requested_by) === String(state.user?.id); const r = route(row.id); if (filter === 'mine') return mine; if (filter === 'revision') return row.request_status === 'needs_revision' && mine; if (filter === 'active') return ['pending','in_review','needs_revision'].includes(row.request_status); if (filter === 'approved') return row.request_status === 'approved'; if (filter === 'closed') return ['rejected','cancelled'].includes(row.request_status); return !!r?.actionable; };
  function renderSummary() { const host = q('#workbenchSummary'); if (!host) return; const current = state.requests || [], history = state.requestHistory || []; const values = [['Ø§Ù‚Ø¯Ø§Ù… Ù…Ù†', current.filter(row => route(row.id)?.actionable).length], ['Ø¯Ø±Ø®ÙˆØ§Ø³Øªâ€ŒÙ‡Ø§ÛŒ Ù…Ù†', allRows().filter(row => String(row.requested_by) === String(state.user?.id)).length], ['Ù†ÛŒØ§Ø²Ù…Ù†Ø¯ Ø§ØµÙ„Ø§Ø­', current.filter(row => row.request_status === 'needs_revision' && String(row.requested_by) === String(state.user?.id)).length], ['ØªØ£ÛŒÛŒØ¯Ø´Ø¯Ù‡', history.filter(row => row.request_status === 'approved').length]]; host.innerHTML = values.map(([title, value]) => `<div><b>${fa(value)}</b><span>${title}</span></div>`).join(''); }
  function renderRows() { const body = q('#approvalBody'); if (!body) return; const rows = allRows().filter(matches).sort((a,b) => (Date.parse(b.created_at || 0) || 0) - (Date.parse(a.created_at || 0) || 0)); const names = Object.fromEntries((state.profiles || []).map(person => [person.id, person.display_name || person.full_name || person.email])); body.innerHTML = rows.length ? rows.map(row => { const routing = route(row.id), action = row.request_status === 'needs_revision' && String(row.requested_by) === String(state.user?.id) ? `<button class="primary" data-revise-request="${row.id}">Ø§ØµÙ„Ø§Ø­ Ùˆ Ø§Ø±Ø³Ø§Ù„ Ù…Ø¬Ø¯Ø¯</button>` : routing?.actionable ? `<button class="primary" data-review-request="${row.id}">Ø¨Ø±Ø±Ø³ÛŒ</button>` : 'â€”'; const status = routing?.stage_title ? `Ù…Ø±Ø­Ù„Ù‡ ${fa(routing.stage_no)}: ${esc(routing.stage_title)} â€” ${esc(routing.approver_names || 'â€”')}` : row.request_status === 'approved' ? 'ØªØ£ÛŒÛŒØ¯ Ù†Ù‡Ø§ÛŒÛŒ' : row.request_status === 'rejected' ? 'Ø±Ø¯Ø´Ø¯Ù‡' : row.request_status === 'cancelled' ? 'Ù„ØºÙˆØ´Ø¯Ù‡' : row.request_status === 'needs_revision' ? 'Ù†ÛŒØ§Ø²Ù…Ù†Ø¯ Ø§ØµÙ„Ø§Ø­' : 'Ø¯Ø± Ø­Ø§Ù„ ØªØ£ÛŒÛŒØ¯'; return `<tr data-request-id="${row.id}"><td>${fa(row.id)}</td><td>${esc(names[row.requested_by] || row.requester_name_snapshot || 'â€”')}</td><td>${esc(labels[row.request_type] || row.request_type || 'â€”')}</td><td>${esc(row.proposed_data?.title || state.tasks.find(task => String(task.id) === String(row.task_id))?.title || 'â€”')}</td><td>${dateTime(row.created_at)}</td><td>${status}</td><td>${action}</td></tr>`; }).join('') : '<tr><td colspan="7" class="empty">Ù…ÙˆØ±Ø¯ÛŒ Ø¯Ø± Ø§ÛŒÙ† Ø¨Ø®Ø´ ÙˆØ¬ÙˆØ¯ Ù†Ø¯Ø§Ø±Ø¯.</td></tr>'; }
  function sync() { if (!q('#approvalsView')) return; renderSummary(); renderRows(); q('#approvalsView').classList.toggle('workbench-ready', true); }
  function boot() { document.addEventListener('click', event => { const tab = event.target.closest('[data-workbench-filter]'); if (tab) { filter = tab.dataset.workbenchFilter; qaTabs().forEach(item => item.classList.toggle('active', item === tab)); sync(); } if (event.target.closest('#refreshWorkbench')) { Promise.resolve(window.refresh?.()).catch(error => notify(error.message, true)); } }); if (typeof BamcoNavigation !== 'undefined') BamcoNavigation.on('navigation-after', detail => { if (detail.to === 'approvals') sync(); }); }
  const qaTabs = () => [...document.querySelectorAll('[data-workbench-filter]')];
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true }); else boot();
  window.bamcoApprovalCenter = { sync, state: () => ({ filter }) };
})();
;

