  function ganttMarkup(rows) { const dates = rows.flatMap(row => [row.planned_start, row.planned_end]).filter(Boolean).map(value => new Date(value).getTime()); if (!dates.length) return '<div class="empty">Ø¨Ø±Ø§ÛŒ Ù†Ù…Ø§ÛŒØ´ Ù†ÙˆØ§Ø± Ø²Ù…Ø§Ù†ØŒ ØªØ§Ø±ÛŒØ® Ø´Ø±ÙˆØ¹ Ùˆ Ù¾Ø§ÛŒØ§Ù† Ø¢ÛŒØªÙ…â€ŒÙ‡Ø§ Ø±Ø§ Ø«Ø¨Øª Ú©Ù†ÛŒØ¯.</div>'; const min = Math.min(...dates), max = Math.max(...dates, min + 86400000), span = Math.max(86400000, max - min); return `<div class="gantt-grid">${rows.map(row => { const start = row.planned_start ? new Date(row.planned_start).getTime() : min, end = row.planned_end ? new Date(row.planned_end).getTime() : start + 86400000; const left = Math.max(0, ((start - min) / span) * 100), width = Math.max(2, ((end - start) / span) * 100); return `<div class="gantt-row"><span>${esc(row.title)}</span><div class="gantt-track"><i style="--bar-left:${left}%;--bar-width:${width}%" title="${esc(row.title)} â€” ${fa(Math.round(row.progress || 0))}Ùª"></i></div></div>`; }).join('')}</div>`; }
