async function upload(entryId,file){if(file.size>25*1024*1024)throw Error(`Ø­Ø¬Ù… Â«${file.name}Â» Ø¨ÛŒØ´ Ø§Ø² Û²Ûµ Ù…Ú¯Ø§Ø¨Ø§ÛŒØª Ø§Ø³Øª.`);const ext=file.name.split('.').pop().toLowerCase(),path=`${entryId}/${crypto.randomUUID()}.${ext}`,encoded=path.split('/').map(encodeURIComponent).join('/'),r=await fetch(`${SB_URL}/storage/v1/object/${bucket}/${encoded}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+state.token,'Content-Type':file.type},body:file});if(!r.ok)throw Error('Ø¨Ø§Ø±Ú¯Ø°Ø§Ø±ÛŒ Ø¶Ù…ÛŒÙ…Ù‡ Ø§Ù†Ø¬Ø§Ù… Ù†Ø´Ø¯.');try{await insert('petty_cash_attachments',{entry_id:entryId,storage_path:path,file_name:file.name,mime_type:file.type,file_size:file.size,uploaded_by:state.profile.id})}catch(e){await fetch(`${SB_URL}/storage/v1/object/${bucket}`,{method:'DELETE',headers:{apikey:SB_KEY,Authorization:'Bearer '+state.token,'Content-Type':'application/json'},body:JSON.stringify({prefixes:[path]})});throw e}}
