function load(force=false){if(!isManager())return Promise.resolve();if(loading&&!force)return loading;const view=q('#messageCenterView');view?.classList.add('bamco-view-settling');const refresh=q('#refreshMessageCenter');if(refresh)refresh.disabled=true;loading=(async()=>{try{rows=await selectAll('message_recipient_live_state','select=*&order=recipient_name');render();const err=q('#messageCenterError');if(err)err.textContent=''}catch(error){const err=q('#messageCenterError');if(err)err.textContent=error.message}finally{view?.classList.remove('bamco-view-settling');view?.dispatchEvent(new CustomEvent('bamco-view-data-ready',{bubbles:true}));if(refresh)refresh.disabled=false;loading=null}})();return loading}
